package com.vaccination.dao;

import com.vaccination.model.VaccinationRecord;
import com.vaccination.util.DatabaseConnection;

import java.sql.*;
import java.util.ArrayList;
import java.util.List;

public class VaccinationRecordDAO {

    public VaccinationRecord findById(int recordId) {
        String sql = "SELECT * FROM VaccinationRecords WHERE RecordID = ?";

        try (Connection conn = DatabaseConnection.getInstance().getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {

            stmt.setInt(1, recordId);
            ResultSet rs = stmt.executeQuery();

            if (rs.next()) {
                return extractRecordFromResultSet(rs);
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
        return null;
    }

    public List<VaccinationRecord> findByChildId(int childId) {
        List<VaccinationRecord> records = new ArrayList<>();
        String sql = "SELECT * FROM VaccinationRecords WHERE ChildID = ? ORDER BY VaccinationDate DESC";

        try (Connection conn = DatabaseConnection.getInstance().getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {

            stmt.setInt(1, childId);
            ResultSet rs = stmt.executeQuery();

            while (rs.next()) {
                records.add(extractRecordFromResultSet(rs));
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
        return records;
    }

    public List<VaccinationRecord> findByAppointmentId(int appointmentId) {
        List<VaccinationRecord> records = new ArrayList<>();
        String sql = "SELECT * FROM VaccinationRecords WHERE AppointmentID = ?";

        try (Connection conn = DatabaseConnection.getInstance().getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {

            stmt.setInt(1, appointmentId);
            ResultSet rs = stmt.executeQuery();

            while (rs.next()) {
                records.add(extractRecordFromResultSet(rs));
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
        return records;
    }

    public boolean createRecord(VaccinationRecord record) {
        String sql = "INSERT INTO VaccinationRecords (AppointmentID, ChildID, VaccineID, VaccinationDate, " +
                     "BatchNumber, DoseNumber, AdministeredBy, HealthCheckNotes, VaccinationNotes, " +
                     "SideEffectsReported, NextDoseDate) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";

        try (Connection conn = DatabaseConnection.getInstance().getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {

            stmt.setInt(1, record.getAppointmentId());
            stmt.setInt(2, record.getChildId());
            stmt.setInt(3, record.getVaccineId());
            stmt.setTimestamp(4, Timestamp.valueOf(record.getVaccinationDate()));
            stmt.setString(5, record.getBatchNumber());

            if (record.getDoseNumber() != null) {
                stmt.setInt(6, record.getDoseNumber());
            } else {
                stmt.setNull(6, Types.INTEGER);
            }

            stmt.setInt(7, record.getAdministeredBy());
            stmt.setString(8, record.getHealthCheckNotes());
            stmt.setString(9, record.getVaccinationNotes());
            stmt.setString(10, record.getSideEffectsReported());

            if (record.getNextDoseDate() != null) {
                stmt.setDate(11, Date.valueOf(record.getNextDoseDate()));
            } else {
                stmt.setNull(11, Types.DATE);
            }

            int affected = stmt.executeUpdate();
            if (affected > 0) {
                ResultSet rs = stmt.getGeneratedKeys();
                if (rs.next()) {
                    record.setRecordId(rs.getInt(1));
                }
                return true;
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
        return false;
    }

    private VaccinationRecord extractRecordFromResultSet(ResultSet rs) throws SQLException {
        VaccinationRecord record = new VaccinationRecord();
        record.setRecordId(rs.getInt("RecordID"));
        record.setAppointmentId(rs.getInt("AppointmentID"));
        record.setChildId(rs.getInt("ChildID"));
        record.setVaccineId(rs.getInt("VaccineID"));

        Timestamp vaccinationDate = rs.getTimestamp("VaccinationDate");
        if (vaccinationDate != null) record.setVaccinationDate(vaccinationDate.toLocalDateTime());

        record.setBatchNumber(rs.getString("BatchNumber"));

        int doseNumber = rs.getInt("DoseNumber");
        if (!rs.wasNull()) record.setDoseNumber(doseNumber);

        record.setAdministeredBy(rs.getInt("AdministeredBy"));
        record.setHealthCheckNotes(rs.getString("HealthCheckNotes"));
        record.setVaccinationNotes(rs.getString("VaccinationNotes"));
        record.setSideEffectsReported(rs.getString("SideEffectsReported"));

        Date nextDoseDate = rs.getDate("NextDoseDate");
        if (nextDoseDate != null) record.setNextDoseDate(nextDoseDate.toLocalDate());

        Timestamp createdAt = rs.getTimestamp("CreatedAt");
        if (createdAt != null) record.setCreatedAt(createdAt.toLocalDateTime());

        return record;
    }
}

package com.vaccination.dao;

import com.vaccination.model.Vaccine;
import com.vaccination.model.VaccinationScheduleTemplate;
import com.vaccination.util.DatabaseConnection;

import java.sql.*;
import java.util.ArrayList;
import java.util.List;

public class VaccinationScheduleTemplateDAO {

    public List<VaccinationScheduleTemplate> findByAgeInMonths(double ageInMonths) {
        List<VaccinationScheduleTemplate> templates = new ArrayList<>();
        String sql = "SELECT vst.*, v.* FROM VaccinationScheduleTemplate vst " +
                    "INNER JOIN Vaccines v ON vst.VaccineID = v.VaccineID " +
                    "WHERE vst.AgeInMonths = ? " +
                    "ORDER BY vst.DisplayOrder";

        try (Connection conn = DatabaseConnection.getInstance().getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {

            stmt.setDouble(1, ageInMonths);
            ResultSet rs = stmt.executeQuery();

            while (rs.next()) {
                VaccinationScheduleTemplate template = extractTemplateFromResultSet(rs);
                Vaccine vaccine = extractVaccineFromResultSet(rs);
                template.setVaccine(vaccine);
                templates.add(template);
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }

        return templates;
    }

    public List<VaccinationScheduleTemplate> findRecommendedForAge(double ageInMonths) {
        List<VaccinationScheduleTemplate> templates = new ArrayList<>();
        String sql = "SELECT vst.TemplateID, vst.VaccineID, vst.StageName, vst.AgeInMonths, vst.DoseNumber, " +
                    "vst.Description AS TemplateDescription, vst.IsMandatory, vst.DisplayOrder, vst.CreatedAt AS TemplateCreatedAt, " +
                    "v.VaccineName, v.Manufacturer, v.Description, v.DiseasesPrevented, v.DosageSchedule, " +
                    "v.RecommendedAge, v.Price, v.IsFree, v.IsActive, v.SideEffects, v.Contraindications, v.CreatedAt " +
                    "FROM VaccinationScheduleTemplate vst " +
                    "INNER JOIN Vaccines v ON vst.VaccineID = v.VaccineID " +
                    "WHERE vst.AgeInMonths >= ? AND v.IsActive = 1 " +
                    "ORDER BY vst.AgeInMonths, vst.DisplayOrder";

        try (Connection conn = DatabaseConnection.getInstance().getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {

            stmt.setDouble(1, ageInMonths);
            ResultSet rs = stmt.executeQuery();

            while (rs.next()) {
                VaccinationScheduleTemplate template = extractTemplateFromResultSet(rs);
                Vaccine vaccine = extractVaccineFromResultSet(rs);
                template.setVaccine(vaccine);
                templates.add(template);
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }

        return templates;
    }

    public List<VaccinationScheduleTemplate> findMandatoryByAge(double ageInMonths) {
        List<VaccinationScheduleTemplate> templates = new ArrayList<>();
        String sql = "SELECT vst.*, v.* FROM VaccinationScheduleTemplate vst " +
                    "INNER JOIN Vaccines v ON vst.VaccineID = v.VaccineID " +
                    "WHERE vst.AgeInMonths = ? AND vst.IsMandatory = 1 AND v.IsActive = 1 " +
                    "ORDER BY vst.DisplayOrder";

        try (Connection conn = DatabaseConnection.getInstance().getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {

            stmt.setDouble(1, ageInMonths);
            ResultSet rs = stmt.executeQuery();

            while (rs.next()) {
                VaccinationScheduleTemplate template = extractTemplateFromResultSet(rs);
                Vaccine vaccine = extractVaccineFromResultSet(rs);
                template.setVaccine(vaccine);
                templates.add(template);
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }

        return templates;
    }

    private VaccinationScheduleTemplate extractTemplateFromResultSet(ResultSet rs) throws SQLException {
        VaccinationScheduleTemplate template = new VaccinationScheduleTemplate();
        template.setTemplateId(rs.getInt("TemplateID"));
        template.setVaccineId(rs.getInt("VaccineID"));
        template.setStageName(rs.getString("StageName"));
        template.setAgeInMonths(rs.getDouble("AgeInMonths"));
        template.setDoseNumber(rs.getInt("DoseNumber"));

        try {
            template.setDescription(rs.getString("TemplateDescription"));
        } catch (SQLException e) {
            template.setDescription(rs.getString("Description"));
        }

        template.setMandatory(rs.getBoolean("IsMandatory"));
        template.setDisplayOrder(rs.getInt("DisplayOrder"));

        try {
            Timestamp createdAt = rs.getTimestamp("TemplateCreatedAt");
            if (createdAt != null) {
                template.setCreatedAt(createdAt.toLocalDateTime());
            }
        } catch (SQLException e) {
            Timestamp createdAt = rs.getTimestamp("CreatedAt");
            if (createdAt != null) {
                template.setCreatedAt(createdAt.toLocalDateTime());
            }
        }

        return template;
    }

    private Vaccine extractVaccineFromResultSet(ResultSet rs) throws SQLException {
        Vaccine vaccine = new Vaccine();
        vaccine.setVaccineId(rs.getInt("VaccineID"));
        vaccine.setVaccineName(rs.getString("VaccineName"));
        vaccine.setManufacturer(rs.getString("Manufacturer"));
        vaccine.setDescription(rs.getString("Description"));
        vaccine.setDiseasesPrevented(rs.getString("DiseasesPrevented"));
        vaccine.setDosageSchedule(rs.getString("DosageSchedule"));
        vaccine.setRecommendedAge(rs.getString("RecommendedAge"));
        vaccine.setPrice(rs.getBigDecimal("Price"));
        vaccine.setFree(rs.getBoolean("IsFree"));
        vaccine.setActive(rs.getBoolean("IsActive"));
        vaccine.setSideEffects(rs.getString("SideEffects"));
        vaccine.setContraindications(rs.getString("Contraindications"));

        Timestamp createdAt = rs.getTimestamp("CreatedAt");
        if (createdAt != null) {
            vaccine.setCreatedAt(createdAt.toLocalDateTime());
        }

        return vaccine;
    }
}

